changeSet.sql:

--remove duplicate historical scoring records where the score has not changed

SET ANSI_WARNINGS OFF;
go

if (not exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Score' AND COLUMN_NAME = 'NewEffectiveDate')) 
begin
     alter table metrics.Score add NewEffectiveDate date;
end

if (not exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'ScoreItem' AND COLUMN_NAME = 'NewEffectiveDate')) 
begin
     alter table metrics.ScoreItem add NewEffectiveDate date;
end

if (not exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Score' AND COLUMN_NAME = 'FlagForUpdate')) 
begin
     alter table metrics.Score add FlagForUpdate bit;
end

if (not exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'ScoreItem' AND COLUMN_NAME = 'FlagForUpdate')) 
begin
     alter table metrics.ScoreItem add FlagForUpdate bit;
end

go

begin
	begin try

		begin tran;

		drop table if exists metrics.TempScoreItem
		select * into metrics.TempScoreItem from metrics.ScoreItem;

		drop table if exists metrics.TempScore
		select * into metrics.TempScore from metrics.Score;


		drop table if exists #tempScore;
		create table #tempScore
		(
			AssetUid uniqueidentifier,
			EffectiveDate date,
			EndDate date,
			[Value] decimal (5,3),
			ScoreType int
		);

		drop table if exists #tempScoreItem;
		create table #tempScoreItem
		(
			AssetUid uniqueidentifier,
			MetricAssetUid uniqueidentifier,
			EffectiveDate date,
			EndDate date,
			[Value] bit
		);

		insert into #tempScore
		select	S.AssetUid, 
				min(S.EffectiveDate) as EffectiveDate, 
				case when max(case when S.EndDate is null then 1 else 0 end) = 0 
					then max(S.EndDate) 
					else null 
				end as EndDate, 
				S.[Value],
				S.ScoreType
		from	metrics.Score s	
				outer apply (
					select	max(EffectiveDate) as MinDate 
					from	metrics.Score M
					where	M.AssetUid = S.AssetUid 
							and M.ScoreType = S.ScoreType and M.[Value] <> S.[Value]
							and M.EffectiveDate < S.EffectiveDate
				) R
		group by S.Assetuid, S.Scoretype, S.[Value], R.MinDate
		having	count(*) > 1;


		insert into #tempScoreItem
		select	S.AssetUid, 
				S.MetricAssetUid,
				min(S.EffectiveDate) as EffectiveDate, 
				case when max(case when S.EndDate is null then 1 else 0 end) = 0 
					then max(S.EndDate) 
					else null 
				end as EndDate, 
				S.[Value]
		from	metrics.ScoreItem s	
				outer apply (
					select	max(EffectiveDate) as MinDate 
					from	metrics.ScoreItem M
					where	M.AssetUid = S.AssetUid 
							and M.MetricAssetUid = S.MetricAssetUid and M.[Value] <> S.[Value]
							and M.EffectiveDate < S.EffectiveDate
				) R
		group by S.Assetuid, S.MetricAssetUid, S.[Value], R.MinDate
		having	count(*) > 1;



		update	S
		set		S.NewEffectiveDate = T.EffectiveDate,
				S.FlagForUpdate = 1
		from	metrics.Score S
				inner join #tempScore T on T.AssetUid = S.AssetUid and T.[Value] = S.[Value] and T.ScoreType = S.ScoreType 
					and coalesce(S.EffectiveDate,'0001-01-01') between T.EffectiveDate and coalesce(T.EndDate,'9999-01-01');

		delete	S
		from	metrics.Score S
				inner join #tempScore T on T.AssetUid = S.AssetUid and T.[Value] = S.[Value] and T.ScoreType = S.ScoreType
					and coalesce(S.NewEffectiveDate,'0001-01-01') between T.EffectiveDate and coalesce(T.EndDate,'9999-01-01')
		where	coalesce(S.EndDate,'0001-01-01') <> coalesce(T.EndDate,'0001-01-01');

		update	S
		set		S.EffectiveDate = S.NewEffectiveDate 
		from	metrics.Score S
		where	S.FlagForUpdate = 1
				and not exists (select 1 from metrics.Score where AssetUid = S.AssetUid and ScoreType = S.ScoreType 
				and EffectiveDate = S.EffectiveDate);


		update	S
		set		S.NewEffectiveDate = T.EffectiveDate,
				S.FlagForUpdate = 1
		from	metrics.ScoreItem S
				inner join #tempScoreItem T on T.AssetUid = S.AssetUid and T.[Value] = S.[Value] and T.MetricAssetUid = S.MetricAssetUid 
					and coalesce(S.EffectiveDate,'0001-01-01') between T.EffectiveDate and coalesce(T.EndDate,'9999-01-01');

		delete	S
		from	metrics.ScoreItem S
				inner join #tempScoreItem T on T.AssetUid = S.AssetUid and T.[Value] = S.[Value] and T.MetricAssetUid = S.MetricAssetUid
					and coalesce(S.NewEffectiveDate,'0001-01-01') between T.EffectiveDate and coalesce(T.EndDate,'9999-01-01')
		where	coalesce(S.EndDate,'0001-01-01') <> coalesce(T.EndDate,'0001-01-01');

		update	S
		set		S.EffectiveDate = S.NewEffectiveDate 
		from	metrics.ScoreItem S
		where	S.FlagForUpdate = 1
		and not exists (select 1 from metrics.Scoreitem where AssetUid = S.AssetUid
			and MetricAssetUid = S.MetricAssetUid and EffectiveDate = S.NewEffectiveDate);

		drop table if exists #tempScore;
		drop table if exists #tempScoreItem;

		commit tran;

	end try
	begin catch
		select ERROR_MESSAGE() as ErrorMessage;
		rollback tran;
	end catch
end


if (exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Score' AND COLUMN_NAME = 'NewEffectiveDate')) 
begin
     alter table metrics.Score drop column NewEffectiveDate;
end

if (exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'ScoreItem' AND COLUMN_NAME = 'NewEffectiveDate')) 
begin
     alter table metrics.ScoreItem drop column NewEffectiveDate;
end

if (exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'Score' AND COLUMN_NAME = 'FlagForUpdate')) 
begin
     alter table metrics.Score drop column FlagForUpdate;
end

if (exists (SELECT * FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'metrics' and TABLE_NAME = 'ScoreItem' AND COLUMN_NAME = 'FlagForUpdate')) 
begin
     alter table metrics.ScoreItem drop column FlagForUpdate;
end
